class Solution {
public:
    int maxSumDivThree(vector<int>& nums) {
        vector<int> dp = {0, (int)-1e9, (int)-1e9};
        for (int x : nums) {
            vector<int> nxt = dp;
            for (int r = 0; r < 3; ++r) {
                int nr = (r + x) % 3;
                nxt[nr] = max(nxt[nr], dp[r] + x);
            }
            dp = move(nxt);
        }
        return dp[0];
    }
};

class Solution {
    public int maxSumDivThree(int[] nums) {
        int[] dp = new int[]{0, (int)-1e9, (int)-1e9};
        for (int x : nums) {
            int[] nxt = dp.clone();
            for (int r = 0; r < 3; r++) {
                int nr = (r + x) % 3;
                nxt[nr] = Math.max(nxt[nr], dp[r] + x);
            }
            dp = nxt;
        }
        return dp[0];
    }
}

var maxSumDivThree = function(nums) {
    let dp = [0, -Infinity, -Infinity];
    for (const x of nums) {
        const nxt = [...dp];
        for (let r = 0; r < 3; r++) {
            const nr = (r + x) % 3;
            nxt[nr] = Math.max(nxt[nr], dp[r] + x);
        }
        dp = nxt;
    }
    return dp[0];
};
